INSERT INTO `bidding_notice_external` VALUES (2097233376895467521,'1','2026-09-08 15:59:36','1','2026-09-08 15:59:36',_binary '\0','QYZB',NULL,'2026年度科技成果鉴定项目直接采购公示','https://qyzb.shccmg.com/cms/default/webfile/1ywgg/20260907/1281652783254077440.html','fca465fa4b86eff46d903635d7636982832b1fb9cd4d6e42189fa093ed920f06','acab1e7b8a0d95dc135ce103be5c3c42062720e840fbf63c40f8f43fb64fe16c','HTML','<p class=\"MsoNormal\" style=\"text-align: center;\" align=\"center\"><strong><span style=\"font-family: 宋体; font-size: 14pt;\"><span style=\"font-family: Calibri;\">2026</span><span style=\"font-family: 宋体;\">年度科技成果鉴定项目直接采购公示</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"margin: 0pt; text-indent: 21pt; padding: 0pt; line-height: 15.75pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体;\">蒲城清洁能源化工有限责任公司</span><span style=\"font-family: 宋体;\">2026年度科技成果鉴定服务项目采购拟采用直接采购方式进行采购，特此公示。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin: 0pt; text-indent: 0pt; padding: 0pt; line-height: 15.75pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><strong><span class=\"16\" style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">一、潜在供应商</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin: 0pt; text-indent: 21pt; padding: 0pt; line-height: 15.75pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">陕西省石油和化学工业联合会</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0pt; text-indent: 0pt; padding: 0pt; line-height: 15.75pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><strong><span class=\"16\" style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">二、谈判采购依据</span></strong></p>\n<p class=\"p\" style=\"margin: 0pt; text-indent: 21pt; padding: 0pt; line-height: 15.75pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">2026年度科技成果鉴定服务项目</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体;\">，该项目不属于依法必须招标项目。公司</span><span style=\"font-family: 宋体;\">&ldquo;DMT0-II甲醇制烯烃节能绿色关键技术开发及工业应用&rdquo;项目计划申报2026年度省科技进步奖，目前资料准备阶段需进行科技成果鉴定。陕西省石油和化学工业联合会。担任全省性行业协会商会能源化工小组长单位，其组织鉴定的专家资源覆盖石化全产业链，专业匹配度高；项目当前已进入申报省奖的关键阶段，成果鉴定工作具有极强的时间窗口要求。</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体;\">按照《陕西煤业化工集团有限责任公司服务采购管理办法》相关规定，符合</span><span style=\"font-family: 宋体;\">&ldquo;因项目需求，需采用直接采购方式&rdquo;的情形</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">。鉴于上述情况，本项目拟与陕西省石油和化学工业联合会进行直接采购。</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0pt; text-indent: 0pt; padding: 0pt; line-height: 15.75pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><strong><span class=\"16\" style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">三、公示期限</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin: 0pt; text-indent: 21pt; padding: 0pt; line-height: 15.75pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><u><span style=\"font-fami